#include "numerics.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace hour_local;
V full_step_cycle(const Problem&p,V w,const Options&o){int n=p.p.n;V z=w.head(n),dual=w.tail(w.size()-n);auto blocks=blocks_for(p,o);for(int pass=0;pass<3;++pass)for(const auto&b:blocks){auto e=p.evaluate(z);Mat H=e.objective.H;V g=e.objective.g;for(int r=0;r<dual.size();++r){const auto&a=e.rows[r].value;double f=dual[r]+o.rho*a.a;g+=f*a.g;H+=f*a.H+o.rho*a.g*a.g.transpose();}int nb=b.size();Mat A(nb,nb);V rhs(nb);for(int i=0;i<nb;++i){rhs[i]=-g[b[i]];for(int j=0;j<nb;++j)A(i,j)=H(b[i],b[j]);}Eigen::SelfAdjointEigenSolver<Mat>eig(A);double shift=std::max(0.,1e-6*std::max(1.,A.diagonal().cwiseAbs().maxCoeff())-eig.eigenvalues().minCoeff());A.diagonal().array()+=shift;V d=A.ldlt().solve(rhs);for(int i=0;i<nb;++i)z[b[i]]+=d[i];}dual+=o.rho*residuals(p.evaluate(z));w.head(n)=z;w.tail(dual.size())=dual;return w;}
int main(int argc,char**argv){try{std::filesystem::path out=argc>1?argv[1]:"results";std::filesystem::create_directories(out);std::ofstream csv(out/"iteration_spectrum.csv"),modes(out/"slow_modes.csv"),validation(out/"spectrum_validation.csv");csv<<std::setprecision(16)<<"N,partition,rho,blocks_per_pass,regularized_blocks,spectral_radius,predicted_cycles_for_1e6_reduction,predicted_block_visits,dual_fraction,global_reference_curvature\n";modes<<std::setprecision(16)<<"N,partition,rho,row,kind,index,mode_real,mode_imag,mode_abs\n";validation<<std::setprecision(16)<<"N,partition,rho,directional_relative_error,passed\n";
 for(int N:{2,8,32}){auto c=chain_case(N);double E=energy(c.model,c.initial)-minimum_energy(c.model);Problem p(c.model,c.initial,1./60,E);Options q;auto ref=solve(p,q);if(!ref.converged)throw std::runtime_error("joint_reference_failed");auto e=p.evaluate(ref.z);Mat J=jacobian(e),H=e.objective.H;int n=p.p.n,k=J.rows();for(int r=0;r<k;++r)H+=ref.dual[r]*e.rows[r].value.H;double curvature=reduced_curvature(p,ref);
 for(std::string partition:{"split","vertex_full","edge_full","global"})for(double rho:{1.,10.,100.,1000.}){Options o;o.partition=partition;o.rho=rho;auto blocks=blocks_for(p,o);Mat A=H+rho*J.transpose()*J,P=Mat::Identity(n,n),Q=Mat::Zero(n,k);int shifted=0;
   for(int pass=0;pass<3;++pass)for(const auto&b:blocks){int nb=b.size();Mat local(nb,nb),rows(nb,n),jr(nb,k);for(int i=0;i<nb;++i){rows.row(i)=A.row(b[i]);jr.row(i)=J.col(b[i]).transpose();for(int j=0;j<nb;++j)local(i,j)=A(b[i],b[j]);}Eigen::SelfAdjointEigenSolver<Mat>eig(local);double floor=1e-6*std::max(1.,local.diagonal().cwiseAbs().maxCoeff()),shift=std::max(0.,floor-eig.eigenvalues().minCoeff());if(shift){local.diagonal().array()+=shift;++shifted;}auto ldlt=local.ldlt();Mat dp=ldlt.solve(rows*P),dq=ldlt.solve(rows*Q+jr);for(int i=0;i<nb;++i){P.row(b[i])-=dp.row(i);Q.row(b[i])-=dq.row(i);}}
   Mat T=Mat::Zero(n+k,n+k);T.topLeftCorner(n,n)=P;T.topRightCorner(n,k)=Q;T.bottomLeftCorner(k,n)=rho*J*P;T.bottomRightCorner(k,k)=Mat::Identity(k,k)+rho*J*Q;
   if(partition=="edge_full"&&rho==100){V w(n+k),direction(n+k);w.head(n)=ref.z;w.tail(k)=ref.dual;for(int i=0;i<n+k;++i)direction[i]=std::sin(.3+i*.7);direction.normalize();double eps=1e-5;V fd=(full_step_cycle(p,w+eps*direction,o)-full_step_cycle(p,w-eps*direction,o))/(2*eps),predicted=T*direction;double error=(fd-predicted).norm()/std::max(1e-12,predicted.norm());bool pass=error<1e-3;validation<<N<<','<<partition<<','<<rho<<','<<error<<','<<pass<<'\n';if(!pass)throw std::runtime_error("iteration_spectrum_derivative_failed");}
   Eigen::EigenSolver<Mat>eig(T,true);Eigen::Index ix;double radius=eig.eigenvalues().cwiseAbs().maxCoeff(&ix);auto mode=eig.eigenvectors().col(ix).eval();double dualfrac=mode.tail(k).squaredNorm()/mode.squaredNorm(),cycles=radius<1?std::log(1e-6)/std::log(radius):-1;csv<<N<<','<<partition<<','<<rho<<','<<blocks.size()<<','<<shifted<<','<<radius<<','<<cycles<<','<<cycles*3*blocks.size()<<','<<dualfrac<<','<<curvature<<'\n';for(int r=0;r<k;++r)modes<<N<<','<<partition<<','<<rho<<','<<r<<','<<int(e.rows[r].kind)<<','<<e.rows[r].index<<','<<mode[n+r].real()<<','<<mode[n+r].imag()<<','<<std::abs(mode[n+r])<<'\n';csv.flush();std::cout<<N<<' '<<partition<<' '<<rho<<" radius="<<radius<<'\n';}
 }
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
